      this.db.query("UPDATE attempts SET state = 'running', started_at = ?1 WHERE id = ?2").run(event.recordedAt, event.payload.attemptId);
      const row = this.db.query("SELECT invocation_id as invocationId FROM attempts WHERE id = ?1").get(event.payload.attemptId);
