class BunVerifierProcess {
  async execute(input) {
    let child;
    try {
      child = Bun.spawn([input.executable, ...input.args], {
        cwd: input.cwd,
        env: { ...process.env, ...input.env },
        stdout: "pipe",
        stderr: "pipe"
      });
    } catch (cause) {
      return {
        exitCode: null,
        signal: null,
        timedOut: false,
        spawnError: String(cause),
        stdout: new Uint8Array,
        stderr: new Uint8Array
      };
    }
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill();
    }, input.timeoutMs);
    try {
      const [exitCode, stdout, stderr] = await Promise.all([
        child.exited,
        new Response(child.stdout).arrayBuffer(),
        new Response(child.stderr).arrayBuffer()
      ]);
      return {
        exitCode,
        signal: null,
        timedOut,
        spawnError: null,
        stdout: new Uint8Array(stdout),
        stderr: new Uint8Array(stderr)
      };
    } catch (cause) {
      return {
        exitCode: null,
        signal: null,
        timedOut,
        spawnError: String(cause),
        stdout: new Uint8Array,
        stderr: new Uint8Array
      };
    } finally {
      clearTimeout(timer);
    }
  }
}
